scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
	scwin.simulateWrapper("#grid1_column2", "drag-n-drop", {
		dx: 0,
		dy: -50
	});
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox').length == 17;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_labelDiv')[0].click()");
    WebSquare.wUnit.addCommand("pause", "100");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
